/* @lc app=leetcode id=964 lang=kotlin */
class Solution { fun leastOpsExpressTarget(x: Int, y: Int): Int = generateSequence(intArrayOf(y, 0, 0, 0)) { s -> if (s[0] == 0) null else (s[0] % x).let { rem -> intArrayOf( s[0] / x, if (s[3] > 0) minOf(rem * s[3] + s[1], (rem + 1) * s[3] + s[2]) else rem * 2, if (s[3] > 0) minOf((x - rem) * s[3] + s[1], (x - rem - 1) * s[3] + s[2]) else (x - rem) * 2, s[3] + 1 ) } }.last().let { minOf(it[1], it[3] + it[2]) - 1 } }